package com.pousadamareal.handler;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.pousadamareal.model.*;
import com.pousadamareal.repository.RoomRepository;
import com.pousadamareal.service.DocumentGenerator;
import com.pousadamareal.service.ReservationService;
import io.javalin.http.Context;
import io.javalin.http.HttpStatus;

import java.math.BigDecimal;
import java.sql.SQLException;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Map;
import java.util.Optional;

public class ReservationHandler {

    public static void create(Context ctx) {
        try {
            String body = ctx.body();
            JsonObject json = JsonParser.parseString(body).getAsJsonObject();

            if (!json.has("roomNumber") || !json.has("guestName") || !json.has("guestEmail") ||
                !json.has("checkIn") || !json.has("checkOut") || !json.has("guests") || !json.has("ratePlan")) {
                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Campos obrigatórios faltam"));
                return;
            }

            int roomNumber;
            String guestName;
            String guestEmail;
            String guestCpf = null;
            String companyCnpj = null;
            String companyName = null;
            String guestPassport = null;
            String guestCountry = null;
            LocalDate checkIn;
            LocalDate checkOut;
            int guests;
            RatePlan ratePlan;

            try {
                roomNumber = json.get("roomNumber").getAsInt();
                guestName = json.get("guestName").getAsString();
                guestEmail = json.get("guestEmail").getAsString();
                checkIn = LocalDate.parse(json.get("checkIn").getAsString());
                checkOut = LocalDate.parse(json.get("checkOut").getAsString());
                guests = json.get("guests").getAsInt();
                ratePlan = RatePlan.valueOf(json.get("ratePlan").getAsString());
            } catch (NumberFormatException | DateTimeParseException e) {
                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Formato inválido"));
                return;
            }

            int identificationCount = 0;
            if (json.has("guestCpf")) {
                guestCpf = json.get("guestCpf").getAsString();
                identificationCount++;
            }
            if (json.has("companyCnpj")) {
                companyCnpj = json.get("companyCnpj").getAsString();
                identificationCount++;
            }
            if (json.has("guestPassport")) {
                guestPassport = json.get("guestPassport").getAsString();
                identificationCount++;
            }

            if (identificationCount != 1) {
                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Deve informar exatamente um tipo de identificação"));
                return;
            }

            if (json.has("companyCnpj") && !json.has("companyName")) {
                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "companyName é obrigatório com companyCnpj"));
                return;
            }

            if (json.has("guestPassport") && !json.has("guestCountry")) {
                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "guestCountry é obrigatório com guestPassport"));
                return;
            }

            if (json.has("companyName")) {
                companyName = json.get("companyName").getAsString();
            }
            if (json.has("guestCountry")) {
                guestCountry = json.get("guestCountry").getAsString();
            }

            try {
                Reservation reservation = ReservationService.create(
                    roomNumber, guestName, guestEmail,
                    guestCpf, companyCnpj, companyName,
                    guestPassport, guestCountry,
                    checkIn, checkOut, guests, ratePlan
                );
                ctx.status(HttpStatus.CREATED).json(toJson(reservation));
            } catch (IllegalArgumentException e) {
                handleError(ctx, e.getMessage());
            }
        } catch (SQLException e) {
            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
        } catch (Exception e) {
            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Erro ao processar requisição"));
        }
    }

    public static void get(Context ctx) {
        try {
            long id = Long.parseLong(ctx.pathParam("id"));
            Reservation reservation = ReservationService.getById(id);
            ctx.json(toJson(reservation));
        } catch (NumberFormatException e) {
            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "ID inválido"));
        } catch (IllegalArgumentException e) {
            handleError(ctx, e.getMessage());
        } catch (SQLException e) {
            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
        }
    }

    public static void confirm(Context ctx) {
        try {
            long id = Long.parseLong(ctx.pathParam("id"));
            String body = ctx.body();
            JsonObject json = JsonParser.parseString(body).getAsJsonObject();

            if (!json.has("amountPaid")) {
                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "amountPaid é obrigatório"));
                return;
            }

            BigDecimal amountPaid = json.get("amountPaid").getAsBigDecimal();
            Reservation reservation = ReservationService.confirm(id, amountPaid);
            ctx.json(toJson(reservation));
        } catch (NumberFormatException e) {
            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "ID ou valor inválido"));
        } catch (IllegalArgumentException e) {
            handleError(ctx, e.getMessage());
        } catch (SQLException e) {
            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
        } catch (Exception e) {
            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Erro ao processar requisição"));
        }
    }

    public static void cancel(Context ctx) {
        try {
            long id = Long.parseLong(ctx.pathParam("id"));
            Reservation reservation = ReservationService.cancel(id);
            ctx.json(toJson(reservation));
        } catch (NumberFormatException e) {
            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "ID inválido"));
        } catch (IllegalArgumentException e) {
            handleError(ctx, e.getMessage());
        } catch (SQLException e) {
            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
        }
    }

    public static void checkIn(Context ctx) {
        try {
            long id = Long.parseLong(ctx.pathParam("id"));
            Reservation reservation = ReservationService.checkIn(id);
            ctx.json(toJson(reservation));
        } catch (NumberFormatException e) {
            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "ID inválido"));
        } catch (IllegalArgumentException e) {
            handleError(ctx, e.getMessage());
        } catch (SQLException e) {
            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
        }
    }

    public static void checkOut(Context ctx) {
        try {
            long id = Long.parseLong(ctx.pathParam("id"));
            Reservation reservation = ReservationService.checkOut(id);

            Optional<Room> room = RoomRepository.findByNumber(reservation.roomNumber());
            Document document = DocumentGenerator.generate(reservation, room.get());

            ctx.json(documentToJson(document));
        } catch (NumberFormatException e) {
            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "ID inválido"));
        } catch (IllegalArgumentException e) {
            handleError(ctx, e.getMessage());
        } catch (SQLException e) {
            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
        }
    }

    public static void getDocument(Context ctx) {
        try {
            long id = Long.parseLong(ctx.pathParam("id"));
            Reservation reservation = ReservationService.getById(id);

            if (reservation.status() == ReservationStatus.PENDING || reservation.status() == ReservationStatus.CANCELLED) {
                ctx.status(409).json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Documento não disponível"));
                return;
            }

            Optional<Room> room = RoomRepository.findByNumber(reservation.roomNumber());
            Document document = DocumentGenerator.generate(reservation, room.get());

            ctx.json(documentToJson(document));
        } catch (NumberFormatException e) {
            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "ID inválido"));
        } catch (IllegalArgumentException e) {
            handleError(ctx, e.getMessage());
        } catch (SQLException e) {
            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
        }
    }

    private static void handleError(Context ctx, String error) {
        switch (error) {
            case "ROOM_NOT_FOUND":
                ctx.status(404).json(Map.of("error", "ROOM_NOT_FOUND", "message", "Quarto não encontrado"));
                break;
            case "RESERVATION_NOT_FOUND":
                ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reserva não encontrada"));
                break;
            case "ROOM_UNAVAILABLE":
                ctx.status(409).json(Map.of("error", "ROOM_UNAVAILABLE", "message", "Quarto não está disponível"));
                break;
            case "CAPACITY_EXCEEDED":
                ctx.status(422).json(Map.of("error", "CAPACITY_EXCEEDED", "message", "Excedeu a capacidade do quarto"));
                break;
            case "OPERATION_NOT_ALLOWED":
                ctx.status(409).json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Operação não permitida"));
                break;
            case "INVALID_REQUEST":
                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Requisição inválida"));
                break;
            default:
                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", error));
        }
    }

    private static Map<String, Object> toJson(Reservation reservation) {
        return Map.ofEntries(
            Map.entry("id", reservation.id()),
            Map.entry("roomNumber", reservation.roomNumber()),
            Map.entry("guestName", reservation.guestName()),
            Map.entry("guestEmail", reservation.guestEmail()),
            Map.entry("guestCpf", reservation.guestCpf()),
            Map.entry("companyCnpj", reservation.companyCnpj()),
            Map.entry("companyName", reservation.companyName()),
            Map.entry("guestPassport", reservation.guestPassport()),
            Map.entry("guestCountry", reservation.guestCountry()),
            Map.entry("checkIn", reservation.checkIn().toString()),
            Map.entry("checkOut", reservation.checkOut().toString()),
            Map.entry("guests", reservation.guests()),
            Map.entry("ratePlan", reservation.ratePlan().name()),
            Map.entry("nights", reservation.nights()),
            Map.entry("subtotal", reservation.subtotal()),
            Map.entry("discount", reservation.discount()),
            Map.entry("total", reservation.total()),
            Map.entry("status", reservation.status().name()),
            Map.entry("amountPaid", reservation.amountPaid()),
            Map.entry("refund", reservation.refund())
        );
    }

    private static Map<String, Object> documentToJson(Document document) {
        return Map.ofEntries(
            Map.entry("title", document.title()),
            Map.entry("reservationId", document.reservationId()),
            Map.entry("guestName", document.guestName()),
            Map.entry("guestCpf", document.guestCpf()),
            Map.entry("companyCnpj", document.companyCnpj()),
            Map.entry("companyName", document.companyName()),
            Map.entry("guestPassport", document.guestPassport()),
            Map.entry("guestCountry", document.guestCountry()),
            Map.entry("roomNumber", document.roomNumber()),
            Map.entry("roomType", document.roomType()),
            Map.entry("checkIn", document.checkIn()),
            Map.entry("checkOut", document.checkOut()),
            Map.entry("nights", document.nights()),
            Map.entry("subtotal", document.subtotal()),
            Map.entry("discount", document.discount()),
            Map.entry("total", document.total()),
            Map.entry("text", document.text())
        );
    }
}

