public class ReportHandler {

    public static void occupancy(Context ctx) {
        try {
            String dateStr = ctx.queryParam("date");
            if (dateStr == null || dateStr.isEmpty()) {
                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "date é obrigatório"));
                return;
            }

            LocalDate date = LocalDate.parse(dateStr);
            String report = ReportService.generateOccupancyReport(date);
            ctx.contentType("text/csv; charset=utf-8").result(report);
        } catch (DateTimeParseException e) {
            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Formato de data inválido"));
        } catch (SQLException e) {
            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
        }
    }

